/// ============================================================
/// ENV — build-time configuration (never secrets beyond the public key)
/// ============================================================
///
/// `flutter run --dart-define-from-file=env.json`; env.json is generated by
/// `node --env-file=.env scripts/app-env.mjs` and is git-ignored.
/// ============================================================
library;

abstract final class Env {
  static const supabaseUrl = String.fromEnvironment('SUPABASE_URL');

  /// Public anon / publishable key — safe to ship; row-level security decides access.
  static const supabaseKey = String.fromEnvironment('SUPABASE_ANON_KEY');

  static String get restUrl => '$supabaseUrl/rest/v1/';
  static String storagePublicUrl(String bucket, String path) => '$supabaseUrl/storage/v1/object/public/$bucket/$path';
  static bool get isConfigured => supabaseUrl.isNotEmpty && supabaseKey.isNotEmpty;
}
